import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.B5xlWq8G.js";const p=JSON.parse('{"title":"Automatic updates with observe","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/observe.md","filePath":"en/guide/observe.md","lastUpdated":1792764473000}'),i={name:"en/guide/observe.md"};function n(s,e,r,c,l,u){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="automatic-updates-with-observe" tabindex="-1">Automatic updates with observe <a class="header-anchor" href="#automatic-updates-with-observe" aria-label="Permalink to &quot;Automatic updates with observe&quot;">​</a></h1><p>Applies to components and directives.</p><p><code>observe</code> controls automatic image DOM observation and how often the gallery updates. It watches additions, removals, reordering and attribute changes (such as <code>src</code> and <code>alt</code>) of <code>&lt;img&gt;</code> elements inside the container, including images replaced by rendered Markdown or HTML. Unrelated text, container styling and Viewer.js-generated UI do not trigger gallery updates.</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th><th>Suitable for</th></tr></thead><tbody><tr><td><code>true</code> (default)</td><td>Start a 50ms window at the first image mutation and update once for changes within that window.</td><td>Markdown, HTML or images rendered in successive batches.</td></tr><tr><td><code>0</code></td><td>Add no batching delay, but still update asynchronously. Mutations received before that update runs are combined.</td><td>Infrequent changes that should appear promptly.</td></tr><tr><td>A positive number, such as <code>100</code></td><td>Batch mutations within the specified number of milliseconds.</td><td>Frequent changes, especially with <code>rebuild</code> enabled.</td></tr><tr><td><code>false</code></td><td>Disable automatic image DOM observation. Initial creation, configuration changes and manual <code>update()</code> calls still work.</td><td>Fixed content or manually controlled updates.</td></tr></tbody></table><p>For example, adding 10 <code>&lt;img&gt;</code> elements in one synchronous operation can produce a single update even with <code>0</code>. Adding them in separate asynchronous operations may produce multiple updates with <code>0</code>, while <code>50</code> combines mutations within the same 50ms window.</p><p>The window starts at the first image mutation and is not restarted by later mutations, allowing continuously changing galleries to update periodically. Initial creation is immediate; the delay applies only to subsequent automatic image DOM updates.</p><p>By default, each batch reuses the instance and calls <code>update()</code>. With <code>rebuild</code> enabled, it destroys and recreates the instance instead. <code>observe</code> can change reactively; setting it to <code>false</code> cancels any pending automatic update.</p>',7)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
